B.a0m=new A.c1("Biriktirmeye ba\u015fla","Yat\u0131r\u0131m uygulamas\u0131ndaki sembolik D\xfcnya Endeksi her sabah %1 bile\u015fik getiri sa\u011flar. \u0130stedi\u011finde paran\u0131 \xe7ekebilirsin.",!0)
B.a0n=new A.c1("S\u0131radaki durak","Bulundu\u011fun \xfclkedeki gezi g\xf6revlerini tamamla ve bir gece kal. Haritada a\xe7\u0131k rotalardan yeni bir \xfclke se\xe7.",!0)
B.a0o=new A.c1("\u015eimdi rota senin","Galeri\u2019de \xfc\xe7 foto\u011fraf\u0131n var. D\xfcnya Haritas\u0131\u2019ndan yeni bir \xfclke se\xe7ip a\xe7\u0131k biletleri inceleyebilirsin.",!1)
B.a0p=new A.c1("K\xfc\xe7\xfck hat\u0131ralar","Market uygulamas\u0131ndan yiyecek, ekipman ve \xfclkeye \xf6zg\xfc hediyelik e\u015fyalar alabilirsin. Bunlar s\u0131rt \xe7antanda birikir.",!0)
B.a0q=new A.c1("Yeni bir an\u0131","\u015eehir Rehberi\u2019nden Galeri\u2019ye \xfc\xe7\xfcnc\xfc foto\u011fraf\u0131n\u0131 ekle.",!0)
B.a0r=new A.c1("\u0130kinci \xfclken","D\xfcnya Haritas\u0131\u2019nda ikinci \xfclkeni boya.",!0)
B.a0s=new A.c1("Gelen kutun","Mail uygulamas\u0131nda f\u0131rsatlar\u0131n, davetlerin ve ba\u015far\u0131lar\u0131n birikir. Okudum d\xfc\u011fmesi \xf6d\xfclleri otomatik al\u0131r.",!0)
B.a0t=new A.c1("","",!1)
B.a0u=new A.c1("\xc7ekili\u015fi kazand\u0131n!","\u0130lk u\xe7u\u015fun, iki gece konaklama ve sigorta senin. G\xfcrcistan, S\u0131rbistan veya Bosna-Hersek aras\u0131ndan se\xe7im yapabileceksin.",!1)
B.a0v=new A.c1("\u0130lk kazan\xe7","Mini \u0130\u015fler uygulamas\u0131nda \xfcr\xfcn katalo\u011fu g\xf6revini tamamla. D\xf6rt saatte 14 USD kazanacaks\u0131n.",!0)
B.a0w=new A.c1("\xdc\xe7\xfcnc\xfc \xfclken","D\xfcnya Haritas\u0131\u2019nda \xfc\xe7\xfcnc\xfc \xfclkeni boya.",!0)
B.a0x=new A.c1("Kap\u0131da bir arkada\u015f","Arkada\u015f\u0131n yol i\xe7in sana \xe7ad\u0131r ve uyku tulumu i\xe7eren bir s\u0131rt \xe7antas\u0131 haz\u0131rlam\u0131\u015f. \u015eehir Rehberi\u2019nde hediyeyi al.",!0)
B.a0y=new A.c1("Kendi yolunu se\xe7","Kariyer uygulamas\u0131nda d\xf6rt dijital kariyerden birini ba\u015flat. Her yeni \xfclke ilerlemeni art\u0131r\u0131r.",!0)
B.a0z=new A.c1("\u0130lk ekipman\u0131n","Mini \u0130\u015fler uygulamas\u0131ndan boncuk seti veya ukulele al. Ekipman\u0131n yeni bir i\u015f a\xe7acak.",!0)
B.a0A=new A.c1("Paran\u0131 kontrol et","C\xfczdan\u2019\u0131 a\xe7\u0131p yeni bakiyeni ve ilk kazanc\u0131n\u0131 g\xf6r.",!0)
B.a0B=new A.c1("\xdc\xe7\xfcnc\xfc \xfclkeye do\u011fru","Gezi g\xf6revlerini tamamla ve yeni bir rota se\xe7. Paran yetmiyorsa Mini \u0130\u015fler\u2019den gelir elde et.",!0)
B.a0C=new A.c1("\u0130lk kariyer i\xe7eri\u011fin","Kariyer Rotalar\u0131 uygulamas\u0131nda \xfclkeye \xf6zel 3 saatlik g\xf6revi tamamla. Bu g\xf6rev sadece se\xe7ti\u011fin kariyeri ilerletir.",!0)
B.a0D=new A.c1("\u0130lk foto\u011fraf","\u015eehir Rehberi\u2019nden gez ve foto\u011fraf \xe7ek. Kartpostal\u0131n Galeri\u2019ye eklenecek.",!0)
